export async function validateChallengeResponse(data: unknown) {
  try {
    const { mockFieldSchemaToZod } = await import("@tkwf/tsclient-mock");
    return mockFieldSchemaToZod({ kind: "object", fields: { ...ChallengeResponseSchema } }).safeParse(data);
  } catch {
    throw new Error("zod is required for runtime validation. Run: npm install zod@^4");
  }
};

